4	import { ProtocolError } from "./errors.js";
5	import * as mqtt from "./mqtt.js";
6	
7	const DEFAULT_MAX_PACKET_BYTES = 1048576;
8	const KEEP_ALIVE_GRACE = 1.5;
9	const FIXED_FLAGS = new Map([
10	  [mqtt.PACKET.CONNECT, 0],
11	  [mqtt.PACKET.PUBACK, 0],
12	  [mqtt.PACKET.SUBSCRIBE, 2],
13	  [mqtt.PACKET.PINGREQ, 0],
14	  [mqtt.PACKET.DISCONNECT, 0],
15	]);
16	
17	class ClientConnection {
18	  constructor(broker, socket) {
19	    this.broker = broker;
20	    this.socket = socket;
21	    this.buffer = Buffer.alloc(0);
22	    this.id = null;
23	    this.subscriptions = new Map();
24	    this.inboundPacketIds = new Set();
25	    this.pendingPacketIds = new Set();
26	    this.nextPacketId = 1;
27	    this.keepAlive = 0;
28	    this.timer = null;
29	    this.will = null;
30	    this.graceful = false;
31	    this.closed = false;
32	    socket.setNoDelay(true);
33	    socket.on("data", (chunk) => this.#onData(chunk));
34	    socket.on("error", () => this.destroy(false));
35	    socket.on("close", () => this.#onClose());
36	  }
37	
38	  #onData(chunk) {
39	    this.buffer = this.buffer.length === 0 ? chunk : Buffer.concat([this.buffer, chunk]);
40	    try {
41	      while (this.buffer.length > 1) {
42	        const remaining = mqtt.decodeRemainingLength(this.buffer, 1);
43	        if (remaining === null) {
44	          return;
45	        }
46	        if (remaining.value > this.broker.maxPacketBytes) {
47	          throw new ProtocolError(`packet of ${remaining.value} bytes exceeds the ${this.broker.maxPacketBytes} byte limit`);
48	        }
49	        const total = 1 + remaining.bytes + remaining.value;
50	        if (this.buffer.length < total) {
51	          return;
52	        }
53	        const first = this.buffer[0];
54	        const body = Buffer.from(this.buffer.subarray(1 + remaining.bytes, total));
55	        this.buffer = this.buffer.subarray(total);
56	        this.#touch();
57	        this.#handle(first >> 4, first & 0x0f, body);
58	      }
59	    } catch (error) {
60	      this.fail(error);
61	    }
62	  }
63	
64	  #handle(type, flags, body) {
65	    if (this.id === null && type !== mqtt.PACKET.CONNECT) {
66	      throw new ProtocolError("the first packet of a connection must be CONNECT");
67	    }
68	    if (type !== mqtt.PACKET.PUBLISH && FIXED_FLAGS.get(type) !== flags) {
69	      throw new ProtocolError(`packet type ${type} must use fixed header flags ${FIXED_FLAGS.get(type) ?? 0}`);
70	    }
71	    switch (type) {
72	      case mqtt.PACKET.CONNECT:
