103	  #publish(flags, body) {
104	    const publish = mqtt.decodePublish(flags, body);
105	    if (publish.qos === 0) {
106	      this.broker.publish(publish.topic, publish.payload, { qos: 0, retain: publish.retain });
107	      return;
108	    }
109	    const duplicate = this.inboundPacketIds.has(publish.packetId);
110	    this.inboundPacketIds.add(publish.packetId);
111	    if (!duplicate) {
