28	/** A fixed, varied event set used by the query tests. */
29	function seed(service) {
30	  seedEvent(service, { rule_id: "r1", event: "temp_high", source: "shadow", device_id: "device-1", occurred_at: "2024-01-01T00:00:00.000Z" });
31	  seedEvent(service, { rule_id: "r2", event: "offline", source: "mqtt", device_id: null, topic: "status/2", occurred_at: "2024-01-01T00:00:05.000Z" });
32	  seedEvent(service, { rule_id: "r1", event: "temp_high", source: "shadow", device_id: "device-2", occurred_at: "2024-01-01T00:00:10.000Z" });
33	  seedEvent(service, { rule_id: "r2", event: "offline", source: "mqtt", device_id: null, topic: "status/4", occurred_at: "2024-01-01T00:00:10.000Z" });
34	  seedEvent(service, { rule_id: "r3", event: "temp_high", source: "mqtt", device_id: null, topic: "status/5", occurred_at: "2024-01-01T00:00:20.000Z" });
35	  seedEvent(service, { rule_id: "r4", event: "restored", source: "shadow", device_id: "device-2", occurred_at: "2024-01-01T00:00:30.500Z" });
36	}
