38	async function getJson(started, path) {
39	  const response = await fetch(`${started.httpUrl}/events${path}`);
40	  return { status: response.status, body: await response.json() };
41	}
42	
43	const sequences = (body) => body.events.map((entry) => entry.sequence);
44	
45	test("events without parameters are returned in ascending sequence", async () => {
46	  await withServer(async (started) => {
47	    seed(started.service);
48	    const { status, body } = await getJson(started, "");
49	    assert.equal(status, 200);
50	    assert.deepEqual(sequences(body), [1, 2, 3, 4, 5, 6]);
51	    assert.deepEqual(Object.keys(body), ["events"]);
52	    assert.equal(body.events[0].event, "temp_high");
