56	test("event and source match complete strings exactly and intersect", async () => {
57	  await withServer(async (started) => {
58	    seed(started.service);
59	    assert.deepEqual(sequences(await (await getJson(started, "?event=temp_high")).body), [1, 3, 5]);
60	    assert.deepEqual(sequences(await (await getJson(started, "?event=offline")).body), [2, 4]);
61	    assert.deepEqual(sequences(await (await getJson(started, "?event=temp_hi")).body), []);
62	    assert.deepEqual(sequences(await (await getJson(started, "?source=shadow")).body), [1, 3, 6]);
63	    assert.deepEqual(sequences(await (await getJson(started, "?source=mqtt")).body), [2, 4, 5]);
