65	    assert.deepEqual(sequences(await (await getJson(started, "?event=temp_high&source=mqtt")).body), [5]);
66	    assert.deepEqual(sequences(await (await getJson(started, "?event=restored&source=mqtt")).body), []);
67	  });
68	});
