71	  await withServer(async (started) => {
72	    seed(started.service);
73	    assert.deepEqual(sequences(await (await getJson(started, "?rule_id=r1")).body), [1, 3]);
74	    assert.deepEqual(sequences(await (await getJson(started, "?device_id=device-2")).body), [3, 6]);
75	    assert.deepEqual(sequences(await (await getJson(started, "?device_id=device-2&rule_id=r1")).body), [3]);
76	    assert.deepEqual(sequences(await (await getJson(started, "?rule_id=r1&event=temp_high")).body), [1, 3]);
77	    assert.deepEqual(sequences(await (await getJson(started, "?device_id=device-2&source=shadow&event=restored")).body), [6]);
78	  });
79	});
