81	test("the time window is half open on occurred_at", async () => {
82	  await withServer(async (started) => {
83	    seed(started.service);
84	    const t = "2024-01-01T00:00:";
85	    assert.deepEqual(sequences(await (await getJson(started, `?occurred_after=${encodeURIComponent(`${t}10.000Z`)}`)).body), [3, 4, 5, 6]);
86	    assert.deepEqual(sequences(await (await getJson(started, `?occurred_before=${encodeURIComponent(`${t}10.000Z`)}`)).body), [1, 2]);
87	    assert.deepEqual(
88	      sequences(await (await getJson(started, `?occurred_after=${encodeURIComponent(`${t}05.000Z`)}&occurred_before=${encodeURIComponent(`${t}20.000Z`)}`)).body),
89	      [2, 3, 4],
90	    );
91	    // Millisecond boundaries are honored exactly.
92	    assert.deepEqual(sequences(await (await getJson(started, `?occurred_before=${encodeURIComponent(`${t}30.500Z`)}`)).body), [1, 2, 3, 4, 5]);
93	    assert.deepEqual(sequences(await (await getJson(started, `?occurred_after=${encodeURIComponent(`${t}30.500Z`)}`)).body), [6]);
94	    // A boundary without fractional seconds is still millisecond exact.
95	    assert.deepEqual(sequences(await (await getJson(started, `?occurred_after=${encodeURIComponent("2024-01-01T00:00:00Z")}`)).body), [1, 2, 3, 4, 5, 6]);
96	  });
