107	    const pageThree = (await getJson(started, `?limit=2&after_sequence=${pageTwo.at(-1).sequence}`)).body.events;
108	    assert.deepEqual(sequences({ events: [...pageOne, ...pageTwo, ...pageThree] }), [1, 2, 3, 4, 5, 6]);
109	    // A short last page is honored, and further pages are empty.
110	    assert.deepEqual(sequences(await (await getJson(started, "?limit=1000")).body), [1, 2, 3, 4, 5, 6]);
111	    assert.deepEqual((await getJson(started, "?after_sequence=6")).body.events, []);
