1	import { Buffer } from "node:buffer";
2	
3	import { ProtocolError, ValidationError } from "./errors.js";
4	
5	export const PACKET = Object.freeze({
6	  CONNECT: 1,
7	  CONNACK: 2,
8	  PUBLISH: 3,
9	  PUBACK: 4,
10	  SUBSCRIBE: 8,
11	  SUBACK: 9,
12	  PINGREQ: 12,
13	  PINGRESP: 13,
14	  DISCONNECT: 14,
15	});
16	
17	export const RETURN_CODE = Object.freeze({
18	  ACCEPTED: 0,
19	  UNACCEPTABLE_PROTOCOL_VERSION: 1,
20	  IDENTIFIER_REJECTED: 2,
21	  SERVER_UNAVAILABLE: 3,
22	  BAD_USERNAME_OR_PASSWORD: 4,
23	  NOT_AUTHORIZED: 5,
24	});
25	
26	export const SUBACK_FAILURE = 0x80;
27	export const MAX_REMAINING_LENGTH = 268435455;
28	const MAX_TOPIC_BYTES = 65535;
29	
30	/** Encode a Remaining Length as a 1-4 byte base-128 varint. */
31	export function encodeRemainingLength(value) {
32	  if (!Number.isInteger(value) || value < 0 || value > MAX_REMAINING_LENGTH) {
33	    throw new ValidationError("remaining length must be an integer between 0 and 268435455");
34	  }
35	  const bytes = [];
36	  let remaining = value;
37	  let digit = 0;
38	  do {
39	    digit = remaining % 128;
40	    remaining = Math.floor(remaining / 128);
41	    if (remaining > 0) {
42	      digit |= 0x80;
43	    }
44	    bytes.push(digit);
45	  } while (remaining > 0);
46	  return Buffer.from(bytes);
47	}
48	
49	/** Decode a Remaining Length; returns null when the buffer is incomplete. */
50	export function decodeRemainingLength(buffer, offset = 1) {
51	  let multiplier = 1;
52	  let value = 0;
53	  let index = 0;
54	  for (;;) {
55	    const position = offset + index;
56	    if (position >= buffer.length) {
57	      return null;
58	    }
59	    const digit = buffer[position];
60	    value += (digit & 0x7f) * multiplier;
61	    index += 1;
62	    if ((digit & 0x80) === 0) {
63	      break;
64	    }
65	    if (index >= 4) {
66	      throw new ProtocolError("remaining length must not span more than four bytes");
67	    }
68	    multiplier *= 128;
69	  }
70	  if (value > MAX_REMAINING_LENGTH) {
71	    throw new ProtocolError("remaining length exceeds 268435455");
72	  }
73	  return { value, bytes: index };
74	}
75	
76	export function encodePacket(type, flags, body) {
77	  return Buffer.concat([Buffer.from([(type << 4) | flags]), encodeRemainingLength(body.length), body]);
78	}
79	
80	export function encodeString(value) {
81	  const bytes = Buffer.from(value, "utf8");
82	  const header = Buffer.alloc(2);
83	  header.writeUInt16BE(bytes.length, 0);
84	  return Buffer.concat([header, bytes]);
85	}
86	
87	export function readString(buffer, offset, label) {
88	  if (offset + 2 > buffer.length) {
89	    throw new ProtocolError(`${label} length is truncated`);
90	  }
91	  const length = buffer.readUInt16BE(offset);
92	  const start = offset + 2;
93	  if (start + length > buffer.length) {
94	    throw new ProtocolError(`${label} is truncated`);
95	  }
96	  return { value: buffer.toString("utf8", start, start + length), offset: start + length };
97	}
98	
99	export function validateTopicName(topic) {
100	  if (typeof topic !== "string" || topic.length === 0) {
101	    throw new ValidationError("topic name must be a non-empty string");
102	  }
103	  if (Buffer.byteLength(topic, "utf8") > MAX_TOPIC_BYTES) {
104	    throw new ValidationError("topic name must be at most 65535 bytes");
105	  }
106	  if (topic.includes("\u0000")) {
107	    throw new ValidationError("topic name must not contain U+0000");
108	  }
109	  if (topic.includes("#") || topic.includes("+")) {
110	    throw new ValidationError("topic name must not contain the wildcards # or +");
111	  }
112	  return topic;
113	}
114	
115	export function validateTopicFilter(filter) {
116	  if (typeof filter !== "string" || filter.length === 0) {
117	    throw new ValidationError("topic filter must be a non-empty string");
118	  }
119	  if (Buffer.byteLength(filter, "utf8") > MAX_TOPIC_BYTES) {
120	    throw new ValidationError("topic filter must be at most 65535 bytes");
121	  }
122	  if (filter.includes("\u0000")) {
123	    throw new ValidationError("topic filter must not contain U+0000");
124	  }
125	  const levels = filter.split("/");
126	  levels.forEach((level, index) => {
127	    if (level.includes("#") && (level !== "#" || index !== levels.length - 1)) {
128	      throw new ValidationError("'#' must occupy an entire topic level and be the last level of a filter");
129	    }
130	    if (level.includes("+") && level !== "+") {
131	      throw new ValidationError("'+' must occupy an entire topic level");
132	    }
133	  });
134	  return filter;
135	}
136	
137	/**
138	 * MQTT 3.1.1 section 4.7 matching. `+` matches exactly one level (including an
139	 * empty level), `#` matches the parent level and every level below it, and a
140	 * filter whose first level is a wildcard never matches a `$`-prefixed topic.
141	 */
142	export function topicMatches(filter, topic) {
143	  const filterLevels = filter.split("/");
144	  const topicLevels = topic.split("/");
145	  if ((filterLevels[0] === "#" || filterLevels[0] === "+") && topicLevels[0].startsWith("$")) {
146	    return false;
147	  }
148	  let index = 0;
149	  for (; index < filterLevels.length; index += 1) {
150	    const level = filterLevels[index];
151	    if (level === "#") {
152	      return true;
153	    }
154	    if (index >= topicLevels.length) {
155	      return false;
156	    }
157	    if (level !== "+" && level !== topicLevels[index]) {
158	      return false;
159	    }
160	  }
161	  return index === topicLevels.length;
162	}
163	
164	const MAX_CLIENT_ID_BYTES = 128;
165	
166	export function decodeConnect(body) {
167	  const name = readString(body, 0, "protocol name");
168	  if (name.value !== "MQTT") {
169	    throw new ProtocolError("protocol name must be MQTT", RETURN_CODE.UNACCEPTABLE_PROTOCOL_VERSION);
