import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { DatabaseSync } from "node:sqlite";

const SCHEMA = `
CREATE TABLE IF NOT EXISTS shadows (
  device_id TEXT PRIMARY KEY,
  document TEXT NOT NULL,
  version INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS rules (
  id TEXT PRIMARY KEY,
  document TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS rule_state (
  rule_id TEXT NOT NULL,
  device_id TEXT NOT NULL,
  matched INTEGER NOT NULL,
  PRIMARY KEY (rule_id, device_id)
);
CREATE TABLE IF NOT EXISTS events (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  rule_id TEXT NOT NULL,
  event TEXT NOT NULL,
  source TEXT NOT NULL,
  device_id TEXT,
  topic TEXT,
  value TEXT NOT NULL,
  occurred_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS retained (
  topic TEXT PRIMARY KEY,
  payload TEXT NOT NULL,
  qos INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS idempotency (
  key TEXT PRIMARY KEY,
  operation TEXT NOT NULL,
  response TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS telemetry_samples (
  device_id TEXT NOT NULL,
  metric TEXT NOT NULL,
  ts INTEGER NOT NULL,
  value REAL NOT NULL,
  seq INTEGER PRIMARY KEY AUTOINCREMENT
);
CREATE INDEX IF NOT EXISTS telemetry_query
  ON telemetry_samples (device_id, metric, ts);
`;

export class Store {
  constructor(path) {
    if (path !== ":memory:") {
      mkdirSync(dirname(path), { recursive: true });
    }
    this.database = new DatabaseSync(path);
    this.database.exec("PRAGMA journal_mode = WAL");
    this.database.exec(SCHEMA);
  }

  close() {
    this.database.close();
  }

  transaction(action) {
    this.database.exec("BEGIN IMMEDIATE");
    try {
      const result = action();
      this.database.exec("COMMIT");
      return result;
    } catch (error) {
      this.database.exec("ROLLBACK");
      throw error;
    }
  }

  /**
   * Documents are stored as JSON with their insertion order preserved, so a
   * document read back from the store is byte-identical to the document that
   * was written and an idempotent replay returns the original bytes.
   */
  encode(value) {
    return JSON.stringify(value);
  }

  decode(value) {
    return JSON.parse(value);
  }

  getShadow(deviceId) {
    const row = this.database.prepare("SELECT document FROM shadows WHERE device_id = ?").get(deviceId);
    return row ? this.decode(row.document) : null;
  }

  putShadow(deviceId, document) {
    this.database
      .prepare(
        `INSERT INTO shadows (device_id, document, version) VALUES (?, ?, ?)
         ON CONFLICT(device_id) DO UPDATE SET document = excluded.document, version = excluded.version`,
      )
      .run(deviceId, this.encode(document), document.version);
  }

  getRule(id) {
    const row = this.database.prepare("SELECT document FROM rules WHERE id = ?").get(id);
    return row ? this.decode(row.document) : null;
  }

  insertRule(rule) {
    this.database.prepare("INSERT INTO rules (id, document) VALUES (?, ?)").run(rule.id, this.encode(rule));
  }

  listRules() {
    return this.database
      .prepare("SELECT document FROM rules ORDER BY id")
      .all()
      .map((row) => this.decode(row.document));
  }

  getRuleState(ruleId, deviceId) {
    const row = this.database.prepare("SELECT matched FROM rule_state WHERE rule_id = ? AND device_id = ?").get(ruleId, deviceId);
    return row ? row.matched === 1 : false;
  }

  setRuleState(ruleId, deviceId, matched) {
    this.database
      .prepare(
        `INSERT INTO rule_state (rule_id, device_id, matched) VALUES (?, ?, ?)
         ON CONFLICT(rule_id, device_id) DO UPDATE SET matched = excluded.matched`,
      )
      .run(ruleId, deviceId, matched ? 1 : 0);
  }

  appendEvent(event) {
    const info = this.database
      .prepare("INSERT INTO events (rule_id, event, source, device_id, topic, value, occurred_at) VALUES (?, ?, ?, ?, ?, ?, ?)")
      .run(event.rule_id, event.event, event.source, event.device_id ?? null, event.topic ?? null, this.encode(event.value), event.occurred_at);
    return { sequence: Number(info.lastInsertRowid), ...event };
  }

  listEvents({
    ruleId = null,
    deviceId = null,
    event = null,
    source = null,
    occurredAfter = null,
    occurredBefore = null,
    afterSequence = null,
    limit = null,
  } = {}) {
    // occurred_at is canonical RFC3339 UTC ending in Z; removing the Z yields
    // the form julianday() reads, so the half-open window is exact down to the
    // millisecond rather than a lexical comparison.
    const windowOf = () => "julianday(substr(occurred_at, 1, length(occurred_at) - 1))";
    const clauses = [];
    const parameters = [];
    if (ruleId !== null) {
      clauses.push("rule_id = ?");
      parameters.push(ruleId);
    }
    if (deviceId !== null) {
      clauses.push("device_id = ?");
      parameters.push(deviceId);
    }
    if (event !== null) {
      clauses.push("event = ?");
      parameters.push(event);
    }
    if (source !== null) {
      clauses.push("source = ?");
      parameters.push(source);
    }
    if (occurredAfter !== null) {
      clauses.push(`${windowOf()} >= julianday(?)`);
      parameters.push(occurredAfter);
    }
    if (occurredBefore !== null) {
      clauses.push(`${windowOf()} < julianday(?)`);
      parameters.push(occurredBefore);
    }
    if (afterSequence !== null) {
      clauses.push("sequence > ?");
      parameters.push(afterSequence);
    }
    const where = clauses.length > 0 ? ` WHERE ${clauses.join(" AND ")}` : "";
    if (limit !== null) {
      parameters.push(limit);
    }
    const cap = limit === null ? "" : " LIMIT ?";
    return this.database
      .prepare(`SELECT * FROM events${where} ORDER BY sequence${cap}`)
      .all(...parameters)
      .map((row) => ({
        sequence: row.sequence,
        rule_id: row.rule_id,
        event: row.event,
        source: row.source,
        device_id: row.device_id,
        topic: row.topic,
        value: this.decode(row.value),
        occurred_at: row.occurred_at,
      }));
  }

  putRetained(topic, payload, qos) {
    this.database
      .prepare(
        `INSERT INTO retained (topic, payload, qos) VALUES (?, ?, ?)
         ON CONFLICT(topic) DO UPDATE SET payload = excluded.payload, qos = excluded.qos`,
      )
      .run(topic, payload.toString("base64"), qos);
  }

  deleteRetained(topic) {
    this.database.prepare("DELETE FROM retained WHERE topic = ?").run(topic);
  }

  listRetained() {
    return this.database
      .prepare("SELECT topic, payload, qos FROM retained ORDER BY topic")
      .all()
      .map((row) => ({ topic: row.topic, payload: Buffer.from(row.payload, "base64"), qos: row.qos }));
  }

  getIdempotency(key) {
    const row = this.database.prepare("SELECT operation, response FROM idempotency WHERE key = ?").get(key);
    return row ? { operation: row.operation, response: this.decode(row.response) } : null;
  }

  putIdempotency(key, operation, response) {
    this.database
      .prepare("INSERT INTO idempotency (key, operation, response) VALUES (?, ?, ?)")
      .run(key, operation, this.encode(response));
  }
}

import { ConflictError, NotFoundError, ValidationError } from "./errors.js";
import { topicMatches } from "./mqtt.js";
import { evaluateCondition, identifier, matchedValue, parseRule } from "./rules.js";
import { computeDelta, parseReportedPatch, parseShadowPatch } from "./shadow.js";
import { Store } from "./store.js";
import { mergeValues } from "./values.js";

const SHADOW_PREFIX = "$shadow/";

function byId(left, right) {
  return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
}

function decodePayload(text) {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

export class Service {
  constructor(database, options = {}) {
    this.store = new Store(database);
    this.now = options.now ?? (() => new Date().toISOString());
    this.publisher = null;
  }

  close() {
    this.store.close();
  }

  /** The broker registers itself here so shadow writes can publish deltas. */
  setPublisher(publisher) {
    this.publisher = publisher;
  }

  health() {
    return { status: "ok" };
  }

  getShadow(rawDeviceId) {
    const deviceId = identifier(rawDeviceId, "device id");
    const document = this.store.getShadow(deviceId);
    if (document === null) {
      throw new NotFoundError(`device ${deviceId} has no shadow`);
    }
    return document;
  }

  updateShadow(rawDeviceId, raw, key) {
    const deviceId = identifier(rawDeviceId, "device id");
    const patch = parseShadowPatch(raw);
    return this.#idempotent(key, `update-shadow:${deviceId}`, () => this.applyShadowPatch(deviceId, patch));
  }

  reportState(rawDeviceId, raw, key) {
    const deviceId = identifier(rawDeviceId, "device id");
    const patch = parseReportedPatch(raw);
    return this.#idempotent(key, `report-state:${deviceId}`, () => this.applyShadowPatch(deviceId, patch));
  }

  /**
   * Merge a patch into the shadow of `deviceId`, bump the version, evaluate
   * shadow rules and publish the delta. Used by HTTP writes and by the
   * reserved `$shadow/<deviceId>/update` topic.
   */
  applyShadowPatch(deviceId, patch) {
    const existing = this.store.getShadow(deviceId);
    const state = existing === null
      ? { desired: {}, reported: {} }
      : { desired: structuredClone(existing.state.desired), reported: structuredClone(existing.state.reported) };
    if (patch.desired !== null) {
      mergeValues(state.desired, patch.desired);
    }
    if (patch.reported !== null) {
      mergeValues(state.reported, patch.reported);
    }
    const document = {
      device_id: deviceId,
      state,
      delta: computeDelta(state.desired, state.reported),
      version: (existing?.version ?? 0) + 1,
      updated_at: this.now(),
    };
    this.store.putShadow(deviceId, document);
    this.#evaluateShadowRules(document);
    this.#publishDelta(document);
    return document;
  }

  createRule(raw, key) {
    const rule = parseRule(raw);
    return this.#idempotent(key, `create-rule:${rule.id}`, () => {
      if (this.store.getRule(rule.id) !== null) {
        throw new ConflictError(`rule ${rule.id} already exists`);
      }
      this.store.insertRule(rule);
      return rule;
    });
  }

  events(query = {}) {
    if (query.ruleId !== undefined && query.ruleId !== null) {
      identifier(query.ruleId, "rule id");
    }
    if (query.deviceId !== undefined && query.deviceId !== null) {
      identifier(query.deviceId, "device id");
    }
    return {
      events: this.store.listEvents({
        ruleId: query.ruleId ?? null,
        deviceId: query.deviceId ?? null,
        event: query.event ?? null,
        source: query.source ?? null,
        occurredAfter: query.occurredAfter ?? null,
        occurredBefore: query.occurredBefore ?? null,
        afterSequence: query.afterSequence ?? null,
        limit: query.limit ?? null,
      }),
    };
  }

  /**
   * Called by the broker for every routed publication: the reserved shadow
   * topic is applied first, then mqtt-scoped rules are evaluated once for the
   * published topic.
   */
  handlePublish(topic, payload) {
    if (topic.startsWith(SHADOW_PREFIX)) {
      const parts = topic.split("/");
      if (parts.length === 3 && parts[2] === "update" && parts[1] !== "") {
        let patch = null;
        try {
          identifier(parts[1], "device id");
          patch = parseShadowPatch(JSON.parse(payload.toString("utf8")));
        } catch {
          // A malformed shadow update is still routed to subscribers but never
          // modifies the shadow, and it never raises a broker protocol error.
          patch = null;
        }
        if (patch !== null) {
          this.applyShadowPatch(parts[1], patch);
        }
      }
    }
    const observation = { topic, payload: decodePayload(payload.toString("utf8")), device_id: null };
    for (const rule of this.store.listRules().filter((candidate) => candidate.source === "mqtt")) {
      if (topicMatches(rule.topic, topic) && evaluateCondition(rule, observation)) {
        this.#emit(rule, { device_id: null, topic, value: matchedValue(rule, observation) });
      }
    }
  }

  #idempotent(key, operation, action) {
    if (!key) {
      throw new ValidationError("Idempotency-Key header is required");
    }
    const existing = this.store.getIdempotency(key);
    if (existing !== null) {
      if (existing.operation !== operation) {
        throw new ConflictError("idempotency key was already used for another operation");
      }
      return existing.response;
    }
    return this.store.transaction(() => {
      const response = action();
      this.store.putIdempotency(key, operation, response);
      return response;
    });
  }

  /**
   * Shadow rules are edge triggered: a rule fires when its condition turns
   * from false to true for that device, so repeating a write that leaves the
   * condition true does not emit another event.
   */
  #evaluateShadowRules(document) {
    const rules = this.store
      .listRules()
      .filter((rule) => rule.source === "shadow" && rule.device_id === document.device_id)
      .sort(byId);
    for (const rule of rules) {
      const matched = evaluateCondition(rule, document);
      const previous = this.store.getRuleState(rule.id, document.device_id);
      this.store.setRuleState(rule.id, document.device_id, matched);
      if (matched && !previous) {
        this.#emit(rule, { device_id: document.device_id, topic: null, value: matchedValue(rule, document) });
      }
    }
  }

  #publishDelta(document) {
    if (this.publisher === null || Object.keys(document.delta).length === 0) {
      return;
    }
    this.publisher(`${SHADOW_PREFIX}${document.device_id}/delta`, Buffer.from(JSON.stringify(document.delta), "utf8"), {
      qos: 0,
      retain: false,
    });
  }

  #emit(rule, { device_id: deviceId, topic, value }) {
    return this.store.appendEvent({
      rule_id: rule.id,
      event: rule.event,
      source: rule.source,
      device_id: deviceId,
      topic,
      value,
      occurred_at: this.now(),
    });
  }
}

