import { ValidationError } from "./errors.js";
import { validateTopicFilter } from "./mqtt.js";
import { deepEqual, isPlainObject, readPath, validatePath } from "./values.js";

export const OPERATORS = Object.freeze(["eq", "ne", "gt", "gte", "lt", "lte", "exists", "not_exists", "contains"]);
const UNARY_OPERATORS = new Set(["exists", "not_exists"]);
const RULE_KEYS = new Set(["id", "source", "device_id", "topic", "path", "operator", "value", "event"]);
const IDENTIFIER = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$/;
const EVENT_NAME = /^[a-z][a-z0-9_]{0,63}$/;

export function identifier(value, label) {
  if (typeof value !== "string" || !IDENTIFIER.test(value)) {
    throw new ValidationError(`${label} must be 1 to 100 characters matching [A-Za-z0-9][A-Za-z0-9._:-]*`);
  }
  return value;
}

/**
 * A rule is either shadow-scoped (it watches one device's shadow document) or
 * mqtt-scoped (its topic filter and the decoded payload form the document).
 */
export function parseRule(raw) {
  if (!isPlainObject(raw)) {
    throw new ValidationError("rule must be a JSON object");
  }
  for (const key of Object.keys(raw)) {
    if (!RULE_KEYS.has(key)) {
      throw new ValidationError(`unknown field ${key} in rule`);
    }
  }
  const rule = { id: identifier(raw.id, "rule id"), source: raw.source };
  if (raw.source === "shadow") {
    if (raw.topic !== undefined) {
      throw new ValidationError("a shadow rule must not declare a topic");
    }
    rule.device_id = identifier(raw.device_id, "device id");
  } else if (raw.source === "mqtt") {
    if (raw.device_id !== undefined) {
      throw new ValidationError("an mqtt rule must not declare a device id");
    }
    rule.topic = validateTopicFilter(raw.topic);
  } else {
    throw new ValidationError("source must be shadow or mqtt");
  }
  rule.path = validatePath(raw.path);
  if (!OPERATORS.includes(raw.operator)) {
    throw new ValidationError(`operator must be one of ${OPERATORS.join(", ")}`);
  }
  rule.operator = raw.operator;
  if (UNARY_OPERATORS.has(rule.operator)) {
    if (raw.value !== undefined) {
      throw new ValidationError(`operator ${rule.operator} must not declare a value`);
    }
  } else {
    if (raw.value === undefined) {
      throw new ValidationError(`operator ${rule.operator} requires a value`);
    }
    rule.value = structuredClone(raw.value);
  }
  if (typeof raw.event !== "string" || !EVENT_NAME.test(raw.event)) {
    throw new ValidationError("event must match [a-z][a-z0-9_]* and be at most 64 characters");
  }
  rule.event = raw.event;
  return rule;
}

function ordered(actual, expected) {
  const bothNumbers = typeof actual === "number" && Number.isFinite(actual) && typeof expected === "number" && Number.isFinite(expected);
  const bothStrings = typeof actual === "string" && typeof expected === "string";
  return bothNumbers || bothStrings;
}

function contains(actual, expected) {
  if (Array.isArray(actual)) {
    return actual.some((item) => deepEqual(item, expected));
  }
  if (typeof actual === "string" && typeof expected === "string") {
    return actual.includes(expected);
  }
  return false;
}

export function evaluateCondition(rule, document) {
  const actual = readPath(document, rule.path);
  switch (rule.operator) {
    case "exists":
      return actual !== undefined;
    case "not_exists":
      return actual === undefined;
    case "eq":
      return actual !== undefined && deepEqual(actual, rule.value);
    case "ne":
      return actual !== undefined && !deepEqual(actual, rule.value);
    case "gt":
      return ordered(actual, rule.value) && actual > rule.value;
    case "gte":
      return ordered(actual, rule.value) && actual >= rule.value;
    case "lt":
      return ordered(actual, rule.value) && actual < rule.value;
    case "lte":
      return ordered(actual, rule.value) && actual <= rule.value;
    case "contains":
      return contains(actual, rule.value);
    default:
      throw new ValidationError(`unsupported operator ${rule.operator}`);
  }
}

/** The value recorded with an emitted event; `undefined` is stored as null. */
export function matchedValue(rule, document) {
  const actual = readPath(document, rule.path);
  return actual === undefined ? null : actual;
}

import { ConflictError, NotFoundError, ValidationError } from "./errors.js";
import { topicMatches } from "./mqtt.js";
import { evaluateCondition, identifier, matchedValue, parseRule } from "./rules.js";
import { computeDelta, parseReportedPatch, parseShadowPatch } from "./shadow.js";
import { Store } from "./store.js";
import { mergeValues } from "./values.js";

const SHADOW_PREFIX = "$shadow/";
const TELEMETRY_PREFIX = "$telemetry/";

function byId(left, right) {
  return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
}

function decodePayload(text) {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

export class Service {
  constructor(database, options = {}) {
    this.store = new Store(database);
    this.now = options.now ?? (() => new Date().toISOString());
    this.publisher = null;
  }

  close() {
    this.store.close();
  }

  /** The broker registers itself here so shadow writes can publish deltas. */
  setPublisher(publisher) {
    this.publisher = publisher;
  }

  health() {
    return { status: "ok" };
  }

  getShadow(rawDeviceId) {
    const deviceId = identifier(rawDeviceId, "device id");
    const document = this.store.getShadow(deviceId);
    if (document === null) {
      throw new NotFoundError(`device ${deviceId} has no shadow`);
    }
    return document;
  }

  updateShadow(rawDeviceId, raw, key) {
    const deviceId = identifier(rawDeviceId, "device id");
    const patch = parseShadowPatch(raw);
    return this.#idempotent(key, `update-shadow:${deviceId}`, () => this.applyShadowPatch(deviceId, patch));
  }

  reportState(rawDeviceId, raw, key) {
    const deviceId = identifier(rawDeviceId, "device id");
    const patch = parseReportedPatch(raw);
    return this.#idempotent(key, `report-state:${deviceId}`, () => this.applyShadowPatch(deviceId, patch));
  }

  /**
   * Merge a patch into the shadow of `deviceId`, bump the version, evaluate
   * shadow rules and publish the delta. Used by HTTP writes and by the
   * reserved `$shadow/<deviceId>/update` topic.
   */
  applyShadowPatch(deviceId, patch) {
    const existing = this.store.getShadow(deviceId);
    const state = existing === null
      ? { desired: {}, reported: {} }
      : { desired: structuredClone(existing.state.desired), reported: structuredClone(existing.state.reported) };
    if (patch.desired !== null) {
      mergeValues(state.desired, patch.desired);
    }
    if (patch.reported !== null) {
      mergeValues(state.reported, patch.reported);
    }
    const document = {
      device_id: deviceId,
      state,
      delta: computeDelta(state.desired, state.reported),
      version: (existing?.version ?? 0) + 1,
      updated_at: this.now(),
    };
    this.store.putShadow(deviceId, document);
    this.#evaluateShadowRules(document);
    this.#publishDelta(document);
    return document;
  }

  createRule(raw, key) {
    const rule = parseRule(raw);
    return this.#idempotent(key, `create-rule:${rule.id}`, () => {
      if (this.store.getRule(rule.id) !== null) {
        throw new ConflictError(`rule ${rule.id} already exists`);
      }
      this.store.insertRule(rule);
      return rule;
    });
  }

  events(query = {}) {
    if (query.ruleId !== undefined && query.ruleId !== null) {
      identifier(query.ruleId, "rule id");
    }
    if (query.deviceId !== undefined && query.deviceId !== null) {
      identifier(query.deviceId, "device id");
    }
    return {
      events: this.store.listEvents({
        ruleId: query.ruleId ?? null,
        deviceId: query.deviceId ?? null,
        event: query.event ?? null,
        source: query.source ?? null,
        occurredAfter: query.occurredAfter ?? null,
        occurredBefore: query.occurredBefore ?? null,
        afterSequence: query.afterSequence ?? null,
        limit: query.limit ?? null,
      }),
    };
  }

  /**
   * Aggregate a device/metric's samples into epoch-aligned buckets over the
   * half-open window [from, to). A device that never published a sample is a
   * normal result with empty buckets; it never creates a shadow or an event.
   */
  telemetry(rawDeviceId, query) {
    const deviceId = identifier(rawDeviceId, "device id");
    const metric = identifier(query.metric, "metric");
    const rows = this.store.aggregateTelemetry({
      deviceId,
      metric,
      fromMs: query.from.millis,
      toMs: query.to.millis,
      bucketSeconds: query.bucketSeconds,
      aggregate: query.aggregate,
    });
