return this.database
  .prepare(
    // Bucket start is floor(ts / width) * width, aligned to the Unix
    // epoch, which also has to be right for pre-1970 (negative)
    // timestamps: SQLite integer division and `%` truncate toward zero,
    // so a negative timestamp needs the width-1 adjustment to floor.
    `SELECT CASE WHEN ts >= 0 THEN (ts / ?) * ? ELSE ((ts - (? - 1)) / ?) * ? END AS bucket,
            ${expression} AS value, COUNT(*) AS count
     FROM telemetry_samples
     WHERE device_id = ? AND metric = ? AND ts >= ? AND ts < ?
     GROUP BY bucket
     ORDER BY bucket ASC`,
  )
  .all(widthMs, widthMs, widthMs, widthMs, widthMs, deviceId, metric, fromMs, toMs)

